namespace BookingSystem.Models;

/// <summary>
/// A conversation with the AI assistant. The id is generated by the server and kept by the widget.
/// </summary>
public class ChatSession
{
    public Guid Id { get; set; }

    /// <summary>Owner; <c>null</c> while the visitor is anonymous.</summary>
    public string? UserId { get; set; }
    public ApplicationUser? User { get; set; }

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;

    /// <summary>Known booking parameters (slot filling state) serialized as JSON.</summary>
    public string SlotsJson { get; set; } = "{}";

    public ICollection<ChatSessionMessage> Messages { get; set; } = [];
}
